#!/usr/bin/env python3
"""Refuse a raw `sys.modules` eviction in `tests/`: go through `tests/module_eviction.py`.

`monkeypatch.delitem(sys.modules, "scripts.core.x")` restores the `sys.modules`
entry at teardown and nothing else. While the entry is gone the first import
binds a NEW module object and rebinds the parent package's attribute
`scripts.core.x` to it; teardown puts the old object back in `sys.modules` and
leaves the attribute pointing at the new one. From then on, in that worker,
`from scripts.core import x` and `import scripts.core.x` name two different
modules, so a later test that patches one and calls through the other patches
nothing. Whether it fails depends only on which tests the xdist worker ran
first -- the lesson `collection-time-pollution`. That is not theory: the #780
push was refused by exactly this, when `test_batch8`'s eviction happened to run
before `test_git_inventory_discovery` in the same worker.

`tests/module_eviction.py` owns the safe form. `evict_module` pins the parent
attribute for restoration alongside the entry; `evict_new_modules` unbinds what
a by-path load pulled in, parent attributes included. #781 folded the last raw
site onto them, so the baseline record ships EMPTY: any site is a new one.

What is deliberately outside the rule: `monkeypatch.setitem(sys.modules, ...)`,
which ADDS a throwaway name and lets pytest delete it again, is not an eviction
and is not a site; neither is reading `sys.modules`, nor `sys.modules.pop`
inside `tests/module_eviction.py` itself, which is the owner. Files under a
`fixtures` directory are executed as children, not collected as tests, and are
not scanned. An empty matched universe is a refusal (S40), never a pass.

The record format is kept identical to `check_wall_clock_form.py` so the gate
can only ever be loosened by a named, reviewed entry: a file above its recorded
count is red, a file below it is a prompt to lower the record, and
`--write-baseline` refuses to raise any count.
"""

from __future__ import annotations

import argparse
import ast
import json
import sys
from pathlib import Path


def _load_repo_runtime_bootstrap():
    pathlib, sys = __import__("pathlib"), __import__("sys")
    marker = ("scripts", "adapter_lib.py")
    parents = pathlib.Path(__file__).resolve().parents
    root = next((p for p in parents if p.joinpath(*marker).is_file()), None)
    if root is not None and str(root) not in sys.path:
        sys.path.insert(0, str(root))


_load_repo_runtime_bootstrap()

from scripts.runtime_bootstrap import import_repo_module  # noqa: E402

_repo_file_listing_module = import_repo_module(__file__, "scripts.core.repo_file_listing")
iter_matching_repo_files = _repo_file_listing_module.iter_matching_repo_files

DEFAULT_SCAN_GLOBS = ("tests/*.py", "tests/**/*.py")
DEFAULT_BASELINE_REL = "charness-artifacts/quality/module-eviction-baseline.json"
SKIP_PATH_PARTS = {"__pycache__", "fixtures"}
OWNER_REL = "tests/module_eviction.py"
BASELINE_SCHEMA = "charness.module-eviction-baseline/v1"


def _dotted(node: ast.AST) -> str:
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return f"{_dotted(node.value)}.{node.attr}"
    return ""


def eviction_sites(source: str, filename: str) -> list[tuple[int, str]]:
    """Every raw `sys.modules` eviction in one module: `(line, spelling)`.

    Three spellings, all resolved through `from sys import modules as m` too, so
    an alias is not a way around the rule: `<anything>.delitem(sys.modules, ...)`
    (the monkeypatch form), `sys.modules.pop(...)`, and `del sys.modules[...]`.
    A string literal that happens to contain one of them is a seeded child's
    body, not an eviction, and is not a site.
    """
    tree = ast.parse(source, filename=filename)
    aliases = {
        alias.asname or alias.name: "sys.modules"
        for node in ast.walk(tree)
        if isinstance(node, ast.ImportFrom) and node.module == "sys"
        for alias in node.names
        if alias.name == "modules"
    }

    def is_sys_modules(node: ast.AST) -> bool:
        name = _dotted(node)
        return name == "sys.modules" or aliases.get(name) == "sys.modules"

    sites: list[tuple[int, str]] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Delete):
            for target in node.targets:
                if isinstance(target, ast.Subscript) and is_sys_modules(target.value):
                    sites.append((node.lineno, "del sys.modules[...]"))
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            if node.func.attr == "pop" and is_sys_modules(node.func.value):
                sites.append((node.lineno, "sys.modules.pop(...)"))
            elif node.func.attr == "delitem" and node.args and is_sys_modules(node.args[0]):
                sites.append((node.lineno, "delitem(sys.modules, ...)"))
    return sorted(sites)


def _iter_scan_paths(repo_root: Path, *, require_git: bool) -> list[Path]:
    paths = iter_matching_repo_files(repo_root, DEFAULT_SCAN_GLOBS, require_git=require_git)
    return [
        path
        for path in paths
        if not (set(path.parts) & SKIP_PATH_PARTS)
        and path.relative_to(repo_root).as_posix() != OWNER_REL
    ]


def select_targets(root: Path, *, paths: list[Path] | None) -> list[Path]:
    """Whole-repo scan by default. When ``paths`` is given (e.g. staged files in
    a pre-commit hook), restrict to the subset of those paths the whole-repo
    scan would also gate, so the owner module, fixture children, and files
    outside ``tests/`` are never gated. Staged-only by design: a pre-existing
    site not in ``paths`` is left to the whole-repo run.
    """
    if paths is None:
        return _iter_scan_paths(root, require_git=False)
    universe = {(p.resolve()) for p in _iter_scan_paths(root, require_git=False)}
    requested = {(p if p.is_absolute() else root / p).resolve() for p in paths}
    return sorted(universe & requested)


def measure(
    repo_root: Path, *, require_git: bool, paths: list[Path] | None = None
) -> tuple[dict[str, list[tuple[int, str]]], int]:
    """Per-file raw eviction sites for every scanned test file, plus the file count."""
    scan_paths = (
        _iter_scan_paths(repo_root, require_git=require_git)
        if paths is None
        else select_targets(repo_root, paths=paths)
    )
    found: dict[str, list[tuple[int, str]]] = {}
    for path in scan_paths:
        relative = path.relative_to(repo_root).as_posix()
        sites = eviction_sites(path.read_text(encoding="utf-8"), str(path))
        if sites:
            found[relative] = sites
    return found, len(scan_paths)


def load_baseline(path: Path) -> dict[str, int]:
    if not path.is_file():
        return {}
    payload = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(payload, dict) or payload.get("schema") != BASELINE_SCHEMA:
        raise SystemExit(f"{path}: not a {BASELINE_SCHEMA} record")
    files = payload.get("files")
    if not isinstance(files, dict) or not all(
        isinstance(k, str) and isinstance(v, int) and v > 0 for k, v in files.items()
    ):
        raise SystemExit(f"{path}: `files` must map test paths to positive site counts")
    return dict(files)


def judge(
    found: dict[str, list[tuple[int, str]]],
    baseline: dict[str, int],
    *,
    selected: set[str] | None = None,
) -> tuple[list[str], list[str]]:
    """`(failures, shrink_prompts)` for the measured tree against the record.

    ``selected`` bounds a path-scoped run to its files: baseline entries
    outside the selection are left to the whole-repo run instead of prompting
    on every staged commit.
    """
    failures: list[str] = []
    prompts: list[str] = []
    for relative, sites in sorted(found.items()):
        allowed = baseline.get(relative, 0)
        if len(sites) > allowed:
            listed = ", ".join(f"{line} {name}" for line, name in sites)
            failures.append(
                f"{relative}: {len(sites)} raw sys.modules eviction(s), baseline {allowed} "
                f"(sites: {listed}); evict through tests/module_eviction.py "
                "(evict_module / evict_new_modules) so no parent package attribute is stranded"
            )
        elif len(sites) < allowed:
            prompts.append(f"{relative}: {len(sites)} < baseline {allowed}; lower the record")
    for relative, allowed in sorted(baseline.items()):
        if relative not in found and (selected is None or relative in selected):
            prompts.append(f"{relative}: 0 < baseline {allowed}; drop it from the record")
    return failures, prompts


def write_baseline(
    path: Path, found: dict[str, list[tuple[int, str]]], previous: dict[str, int]
) -> None:
    files = {relative: len(sites) for relative, sites in sorted(found.items())}
    raised = [rel for rel, count in files.items() if count > previous.get(rel, 0) and previous]
    if raised:
        raise SystemExit(
            "refusing to raise the module-eviction baseline for: " + ", ".join(raised) + "; "
            "the record only shrinks"
        )
    payload = {"schema": BASELINE_SCHEMA, "files": files, "total": sum(files.values())}
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--repo-root", type=Path, required=True)
    parser.add_argument("--require-git-file-listing", action="store_true")
    parser.add_argument("--baseline", type=Path, default=None)
    parser.add_argument("--write-baseline", action="store_true")
    parser.add_argument(
        "--paths",
        nargs="+",
        type=Path,
        default=None,
        help=(
            "Explicit files to check (e.g. staged files in a pre-commit hook). "
            "Restricts the check to the subset of these paths the whole-repo "
            "scan would also gate. Takes precedence over the glob scan; "
            "--require-git-file-listing is then irrelevant."
        ),
    )
    args = parser.parse_args(argv)

    repo_root = args.repo_root.resolve()
    baseline_path = args.baseline or (repo_root / DEFAULT_BASELINE_REL)
    found, scanned = measure(
        repo_root, require_git=args.require_git_file_listing, paths=args.paths
    )
    if not scanned:
        if args.paths is not None:
            print("Validated module-eviction form: no eviction-universe files among --paths.")
            return 0
        raise SystemExit(
            "refusing empty matched universe for check_module_eviction_form "
            f"(scan globs: {', '.join(DEFAULT_SCAN_GLOBS)})."
        )
    previous = load_baseline(baseline_path)
    if args.write_baseline:
        if args.paths is not None:
            raise SystemExit(
                "refusing to write the module-eviction baseline from a path-scoped run; "
                "run without --paths so the record covers the whole universe."
            )
        write_baseline(baseline_path, found, previous)
        total = sum(len(sites) for sites in found.values())
        print(f"Wrote module-eviction baseline: {total} site(s) in {len(found)} file(s).")
        return 0
    selected = (
        None
        if args.paths is None
        else {path.relative_to(repo_root).as_posix() for path in select_targets(repo_root, paths=args.paths)}
    )
    failures, prompts = judge(found, previous, selected=selected)
    for prompt in prompts:
        print(f"ADVISORY: {prompt}", file=sys.stderr)
    if failures:
        for failure in failures:
            print(failure, file=sys.stderr)
        return 1
    total = sum(len(sites) for sites in found.values())
    print(
        f"Validated module-eviction form: {scanned} test file(s) scanned, {total} recorded "
        f"site(s) in {len(found)} file(s), none new."
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Path, adapter, and argument helpers for the reviewer worker runner."""

from __future__ import annotations

import argparse
import hashlib
import os
import runpy
import tempfile
from pathlib import Path
from types import SimpleNamespace
from typing import Any

import yaml


def package_root() -> Path:
    """Find the source or installed plugin root from this module's location."""
    for candidate in Path(__file__).resolve().parents:
        has_schema = (
            candidate / "shared/references/bounded-review-result.schema.json"
        ).is_file() or (
            candidate / "skills/shared/references/bounded-review-result.schema.json"
        ).is_file()
        if has_schema and (
            (candidate / "skills/public/critique/scripts/resolve_adapter.py").is_file()
            or (candidate / "skills/critique/scripts/resolve_adapter.py").is_file()
        ):
            return candidate
    raise RuntimeError("cannot locate Charness package root for reviewer runner")


ROOT = package_root()
WORKER = Path(__file__).resolve().with_name("reviewer_worker.py")
DEFAULT_SCHEMA = next(
    path
    for path in (
        ROOT / "shared/references/bounded-review-result.schema.json",
        ROOT / "skills/shared/references/bounded-review-result.schema.json",
    )
    if path.is_file()
)


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _runtime():
    bootstrap = next(
        (
            ancestor / "scripts" / "runtime_bootstrap.py"
            for ancestor in Path(__file__).resolve().parents
            if (ancestor / "scripts" / "runtime_bootstrap.py").is_file()
        ),
        None,
    )
    if bootstrap is None:
        raise ImportError("runtime_bootstrap.py not found")
    return SimpleNamespace(**runpy.run_path(str(bootstrap)))


def repo_path(repo_root: Path, value: Path) -> Path:
    """Resolve runner paths against the explicit repo root, never launch cwd."""
    return (value if value.is_absolute() else repo_root / value).resolve()


def atomic_write_yaml(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary_name = tempfile.mkstemp(
        prefix=f".{path.name}.", suffix=".pending", dir=path.parent
    )
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(yaml.safe_dump(payload, sort_keys=False))
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary_name, path)
    except Exception:
        try:
            os.unlink(temporary_name)
        except OSError:
            pass
        raise


def adapter(repo_root: Path) -> dict[str, Any]:
    adapter_scripts = (
        ROOT / "skills/public/critique/scripts/resolve_adapter.py",
        ROOT / "skills/critique/scripts/resolve_adapter.py",
    )
    resolver = next((path for path in adapter_scripts if path.is_file()), None)
    if resolver is None:
        raise ValueError("cannot locate critique adapter resolver in the installed package")
    resolver_module = _runtime().load_path_module("charness_reviewer_resolve_adapter", resolver)
    payload = resolver_module.load_adapter(repo_root) or {}
    if not isinstance(payload, dict) or payload.get("valid") is not True:
        raise ValueError("critique adapter is invalid")
    return payload


def parser() -> argparse.ArgumentParser:
    result = argparse.ArgumentParser(description="Run one canonical file-backed review attempt.")
    result.add_argument("--repo-root", type=Path, default=ROOT)
    result.add_argument("--prompt-file", type=Path, required=True)
    result.add_argument("--capability-file", type=Path, required=True)
    result.add_argument("--scope", required=True)
    result.add_argument("--packet-identity", required=True)
    result.add_argument("--reviewed-input-identity", required=True)
    result.add_argument("--attempt-id", required=True)
    result.add_argument("--parent-receipt-identity", required=True)
    result.add_argument("--boundary-fingerprint")
    result.add_argument(
        "--boundary-mode", choices=("read-only-worker", "shared-tree-fingerprint"), default=None
    )
    result.add_argument("--ledger-file", type=Path, required=True)
    result.add_argument("--output-file", type=Path, required=True)
    result.add_argument("--receipt-file", type=Path, required=True)
    result.add_argument("--report-file", type=Path, required=True)
    result.add_argument("--schema-file", type=Path, default=DEFAULT_SCHEMA)
    result.add_argument("--stdout-file", type=Path)
    result.add_argument("--stderr-file", type=Path)
    result.add_argument("--backend", choices=("codex_exec", "claude_p"))
    result.add_argument(
        "--expected-target",
        action="append",
        default=None,
        help=(
            "Opaque admitted target the result must observe; repeat for bundled targets. "
            "Declaring the set opts the attempt into the coverage floor: a schema-valid "
            "result that silently drops a target fails as ReviewerCoverageError instead "
            "of passing on shape alone. The runner never embeds item names beyond "
            "this declaration; the contract only enforces set coverage."
        ),
    )
    result.add_argument("--execution-mode", choices=("file-backed-worker", "typed-subagent"))
    result.add_argument("--timeout-seconds", type=float)
    result.add_argument("--run-id")
    return result


def select_runner(args: argparse.Namespace, repo_root: Path) -> tuple[str, str | None, float]:
    adapter_data = adapter(repo_root).get("data") or {}
    runner = adapter_data.get("reviewer_runner") or {}
    configured_mode = runner.get("mode", "file-backed-worker")
    if args.execution_mode is not None and args.execution_mode != configured_mode:
        raise ValueError(
            f"adapter reviewer_runner.mode={configured_mode!r} is authoritative; "
            f"caller requested {args.execution_mode!r}"
        )
    configured_backend = runner.get("backend")
    if configured_backend == "host-defaulted":
        backend = args.backend
    else:
        if args.backend is not None and args.backend != configured_backend:
            raise ValueError(
                f"adapter reviewer_runner.backend={configured_backend!r} is authoritative; "
                f"caller requested {args.backend!r}"
            )
        backend = configured_backend
    configured_timeout = runner.get("timeout_seconds")
    if (
        configured_timeout is not None
        and args.timeout_seconds is not None
        and args.timeout_seconds != configured_timeout
    ):
        raise ValueError(
            f"adapter reviewer_runner.timeout_seconds={configured_timeout!r} is authoritative; "
            f"caller requested {args.timeout_seconds!r}"
        )
    timeout = (
        configured_timeout
        if configured_timeout is not None
        else (args.timeout_seconds if args.timeout_seconds is not None else 900)
    )
    return configured_mode, backend, timeout
